rulesOnlyRef.rule:
@media (width <= 960px) {
  body { overflow-x: hidden; }
  .session-row { touch-action: pan-y; }
  .app-topbar { z-index: 40; background: var(--bg-raised); border-bottom: 1px solid var(--border-subtle); align-items: center; gap: 8px; height: 48px; padding: 0px 8px; display: flex; position: fixed; to

